// Minimal Cosmic Drift game implementation
// Assumes a <canvas id="game"></canvas> in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const width = (canvas.width = canvas.clientWidth || 800);
  const height = (canvas.height = canvas.clientHeight || 600);

  // Game state
  let ship = { x: width / 2, y: height / 2, angle: 0, speed: 2, radius: 10 };
  const particles = [];
  const asteroids = [];
  let score = 0;
  let gameOver = false;

  // Input handling – mouse & touch set ship direction
  const setDirection = (clientX, clientY) => {
    const rect = canvas.getBoundingClientRect();
    const mx = clientX - rect.left;
    const my = clientY - rect.top;
    ship.angle = Math.atan2(my - ship.y, mx - ship.x);
  };
  canvas.addEventListener('mousemove', e => setDirection(e.clientX, e.clientY));
  canvas.addEventListener('touchmove', e => {
    e.preventDefault();
    const touch = e.touches[0];
    setDirection(touch.clientX, touch.clientY);
  }, { passive: false });

  // Helper functions
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const spawnParticle = () => {
    particles.push({
      x: Math.random() * width,
      y: Math.random() * height,
      radius: 3,
      vx: (Math.random() - 0.5) * 0.5,
      vy: (Math.random() - 0.5) * 0.5,
    });
  };
  const spawnAsteroid = () => {
    const size = 15 + Math.random() * 25;
    asteroids.push({
      x: Math.random() * width,
      y: Math.random() * height,
      radius: size,
      vx: (Math.random() - 0.5) * 1.5,
      vy: (Math.random() - 0.5) * 1.5,
    });
  };

  // Initial spawns
  for (let i = 0; i < 30; i++) spawnParticle();
  for (let i = 0; i < 5; i++) spawnAsteroid();

  const update = () => {
    if (gameOver) return;
    // Move ship forward
    ship.x += Math.cos(ship.angle) * ship.speed;
    ship.y += Math.sin(ship.angle) * ship.speed;

    // Boundary lose condition
    if (ship.x < 0 || ship.x > width || ship.y < 0 || ship.y > height) {
      gameOver = true;
    }

    // Update particles (collect)
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      // Wrap around edges for particles
      if (p.x < 0) p.x = width;
      if (p.x > width) p.x = 0;
      if (p.y < 0) p.y = height;
      if (p.y > height) p.y = 0;
      // Collection check
      if (dist(ship, p) < ship.radius + p.radius) {
        score++;
        particles.splice(i, 1);
        spawnParticle();
      }
    }

    // Update asteroids
    for (const a of asteroids) {
      a.x += a.vx;
      a.y += a.vy;
      // Bounce off walls
      if (a.x < a.radius || a.x > width - a.radius) a.vx *= -1;
      if (a.y < a.radius || a.y > height - a.radius) a.vy *= -1;
      // Collision with ship
      if (dist(ship, a) < ship.radius + a.radius) {
        gameOver = true;
      }
    }
  };

  const draw = () => {
    // Clear
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);

    // Draw particles (glowing)
    ctx.fillStyle = '#0ff';
    for (const p of particles) {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw asteroids
    ctx.fillStyle = '#888';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw ship (triangle)
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo( ship.radius, 0);
    ctx.lineTo(-ship.radius, ship.radius / 2);
    ctx.lineTo(-ship.radius, -ship.radius / 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', width / 2 - 120, height / 2);
    }
  };

  const loop = () => {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };

  // Start loop
  requestAnimationFrame(loop);
})();
